// The Aholo World backdrop: the "Valley of Makers" world generated by Aholo World (3D Gaussian
// splats, .spz) is rendered with Spark behind the final valley, so the
// distant towers, aqueducts and mountains are a real 3D world with parallax rather than a flat
// sky picture. Loaded in the background after the title screen; if it fails or the file is
// missing, the panorama sky simply stays in place.

import * as THREE from 'three';
import { getManifest, BASE } from '../core/Assets';

export interface SplatPlacement {
  position: THREE.Vector3Like;
  scale: number;
  /** Extra yaw after the OpenCV → three.js flip. */
  yaw?: number;
}

export class SplatWorld {
  readonly group = new THREE.Group();
  loaded = false;
  private spark: THREE.Object3D | null = null;
  private mesh: (THREE.Object3D & { opacity?: number }) | null = null;
  /** Visible only when the camera is in this x range (it costs nothing elsewhere). */
  range: [number, number] = [330, 1e9];
  private fade = 0;

  constructor(
    private scene: THREE.Scene,
    private renderer: THREE.WebGLRenderer,
  ) {
    scene.add(this.group);
  }

  async load(key: string, place: SplatPlacement) {
    const file = getManifest().splats?.[key];
    if (!file) return false;
    try {
      const { SparkRenderer, SplatMesh } = await import('@sparkjsdev/spark');
      const spark = new SparkRenderer({ renderer: this.renderer });
      this.scene.add(spark);
      this.spark = spark;
      const mesh = new SplatMesh({ url: BASE + file });
      await mesh.initialized;
      // Aholo World splats use the OpenCV convention (y down, z forward): flip to y up, -z forward
      mesh.quaternion.set(1, 0, 0, 0);
      if (place.yaw) mesh.quaternion.premultiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), place.yaw));
      mesh.position.set(place.position.x, place.position.y, place.position.z);
      mesh.scale.setScalar(place.scale);
      mesh.opacity = 0;
      this.group.add(mesh);
      this.mesh = mesh;
      this.loaded = true;
      return true;
    } catch (err) {
      console.warn('Aholo World splats unavailable, keeping the panorama sky', err);
      return false;
    }
  }

  update(dt: number, camX: number) {
    if (!this.mesh) return;
    const want = camX >= this.range[0] && camX <= this.range[1] ? 1 : 0;
    this.fade += (want - this.fade) * (1 - Math.exp(-dt * 1.5));
    if (this.fade < 0.01 && want === 0) this.fade = 0;
    this.mesh.visible = this.fade > 0.005;
    this.mesh.opacity = this.fade;
    if (this.spark) this.spark.visible = this.mesh.visible;
  }
}
